          translation: 'From sattva, knowledge arises; from rajas, greed; from tamas, negligence, delusion, and ignorance also.',
          hindi: 'सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।',
