          transliteration: 'yasmānnodvijate loko lokānnodvijate ca yaḥ | harṣāmarṣabhayodvegairmukto yaḥ sa ca me priyaḥ ||',
          translation: 'One by whom the world is not agitated, and who is not agitated by the world — who is free from joy, envy, fear, and anxiety — he is dear to Me.',
          hindi: 'जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।',
