          explanation: 'Each guna produces its characteristic fruit in the mind. Sattva produces clear understanding (jnana). Rajas produces greed — always wanting more, never satisfied. Tamas produces negligence (pramada) and delusion (moha). These are not moral judgments but precise descriptions of how different mind-states produce different thoughts and actions.',
          keywords: [],
