          transliteration: 'atha vyavasthitān dṛṣṭvā dhārtarāṣṭrān kapidhvajaḥ | pravṛtte śastrasampāte dhanurudyamya pāṇḍavaḥ ||',
          translation: 'O King, thereafter, seeing the sons of Dhritarashtra arrayed and weapons about to clash, the Pandava (Arjuna), whose banner bore the monkey emblem, picked up his bow.',
