          transliteration: 'mātrāsparśāstu kaunteya śītoṣṇasukhaduḥkhadāḥ | āgamāpāyino\'nityāstāṃstitikṣasva bhārata ||',
          translation: 'The contact of the senses with their objects, O son of Kunti, gives rise to cold and heat, pleasure and pain. These are temporary and fleeting. Bear them patiently, O Bharata.',
