          explanation: 'Krishna introduces the fundamental metaphysical distinction: the "field" (body, mind, senses, and all their modifications) and the "knower of the field" (pure consciousness). The body is the field — it changes, ages, dies. The knower of the field is the eternal witness. Identifying with the field is ignorance; recognizing oneself as the knower is wisdom.',
          keywords: [],
