          explanation: 'Krishna introduces the practice of titiksha (patient endurance). The pairs of opposites — cold-heat, pleasure-pain — arise from sense contact, not from reality itself. They come and go; they are impermanent. The key teaching here is that suffering is not caused by external events but by our reaction to them. By developing titiksha, one learns to observe sensations without reaction, which is the foundation of equanimity.',
