          explanation: 'The three gunas are the fundamental operating modes of all matter and mind. Sattva = clarity, light, harmony. Rajas = energy, passion, restlessness, ambition. Tamas = inertia, heaviness, delusion, lethargy. Every thought, food, action, and environment pushes us toward one of these three states.',
          keywords: [],
