          hindi: 'क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।',
          explanation: 'Krishna states the fundamental law of existence: the cycle of birth and death is inevitable for all embodied beings. Dhruva (certain, fixed) — both birth and death are certainties. The logic is simple: if you lament the inevitable, you create unnecessary suffering. The wise accept what cannot be changed and focus their energy on what can be transformed — their own inner state.',
