          translation: 'You grieve for those who should not be grieved for, and yet you speak words of wisdom. The wise do not grieve for the departed or for those who have not departed.',
          hindi: 'श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।',
          explanation: 'Krishna reveals Arjuna\'s contradiction — he speaks like a wise man but grieves like an ignorant one. The wise understand that the Self is eternal and never dies.',
          keywords: [],
